// Syncs committed Android customizations into the regenerable src-tauri/gen/
// tree. Runs from tauri.conf.json beforeDevCommand / beforeBuildCommand (and is
// safe to run by hand: `npm run sync-android`). No-ops when gen/android does
// not exist (desktop-only checkouts, pre-init state).
//
// The house law (resonance-standards/docs/ANDROID-BUILD-LAWS.md §4): manifest
// extras belong to a script, not to a hand — gen/ is regenerated by
// `tauri android init`, and anything hand-edited inside it is lost. Compass and
// lantern solved it this way first; carried here with the Android microphone
// wave, 2026-08-20.
//
// Covers two of the three post-init steps:
//   1. Kotlin plugin sources (android-extras/*.kt → app package .plugin subdir)
//   2. AndroidManifest.xml — RECORD_AUDIO (the microphone), idempotent insert
// Icons remain a manual step (binary assets, regenerated by `tauri icon`;
// restore KP's art from resonance-assets/logo-icons/sistrum.png afterward).

import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const genAndroid = join(root, 'src-tauri', 'gen', 'android');

if (!existsSync(genAndroid)) {
	console.log('[sync-android-extras] no gen/android — skipping');
	process.exit(0);
}

// 1. Kotlin extras → app module, plugin subpackage
const extrasDir = join(root, 'src-tauri', 'android-extras');
const pluginDir = join(genAndroid, 'app', 'src', 'main', 'java', 'com', 'audhd', 'resonance_sistrum', 'plugin');
if (existsSync(extrasDir)) {
	mkdirSync(pluginDir, { recursive: true });
	for (const file of readdirSync(extrasDir).filter((f) => f.endsWith('.kt'))) {
		copyFileSync(join(extrasDir, file), join(pluginDir, file));
		console.log(`[sync-android-extras] synced ${file}`);
	}
}

// 2. RECORD_AUDIO — the microphone. Anchored on the INTERNET line Tauri always
//    writes; inserted once, never twice.
const manifestPath = join(genAndroid, 'app', 'src', 'main', 'AndroidManifest.xml');
const manifest = readFileSync(manifestPath, 'utf8');
if (!manifest.includes('RECORD_AUDIO')) {
	const anchor = '<uses-permission android:name="android.permission.INTERNET" />';
	if (!manifest.includes(anchor)) {
		console.error('[sync-android-extras] manifest INTERNET anchor not found — add RECORD_AUDIO manually');
		process.exit(1);
	}
	const block =
		anchor +
		'\n    <!-- the record room and the tuner — the microphone (runtime-granted via MediaPermissionPlugin) -->' +
		'\n    <uses-permission android:name="android.permission.RECORD_AUDIO" />';
	writeFileSync(manifestPath, manifest.replace(anchor, block));
	console.log('[sync-android-extras] RECORD_AUDIO inserted');
} else {
	console.log('[sync-android-extras] RECORD_AUDIO already present');
}
